from rules import bounds, dependencies


def solve(data):
    packages = data.get('packages', {})
    names = sorted(packages)
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    required = {}

    for name, spec in data.get('roots', {}).items():
        if name not in packages:
            return {'error': 'unsatisfiable'}
        required.setdefault(name, []).append(bounds(spec))

    best_vector = None
    best_versions = None

    def is_acyclic(selected):
        graph = {
            name: [dep for dep, _ in dependencies(row.get('deps', []), features)]
            for name, row in selected.items()
        }
        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dep in graph[name]:
                if dep not in graph or not visit(dep):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(constraints, selected):
        nonlocal best_vector, best_versions
        pending = sorted(name for name in constraints if name not in selected)
        if not pending:
            if not is_acyclic(selected):
                return
            versions = {name: row['version'] for name, row in selected.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = pending[0]
        forbidden = blocked.get(name, [])
        for row in sorted(packages[name], key=lambda item: item['version'], reverse=True):
            version = row['version']
            if version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue
            if not all(low <= version and (high is None or version <= high)
                       for low, high in constraints[name]):
                continue

            next_constraints = {key: list(value) for key, value in constraints.items()}
            next_selected = dict(selected)
            next_selected[name] = row
            valid = True
            for dep_name, dep_bounds in dependencies(row.get('deps', []), features):
                if dep_name not in packages:
                    valid = False
                    break
                next_constraints.setdefault(dep_name, []).append(dep_bounds)
                if dep_name in next_selected:
                    dep_version = next_selected[dep_name]['version']
                    low, high = dep_bounds
                    if dep_version < low or (high is not None and dep_version > high):
                        valid = False
                        break
            if valid:
                search(next_constraints, next_selected)

    search(required, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def bounds(value):
    """Return inclusive (minimum, maximum) bounds for a version spec."""
    if isinstance(value, dict):
        low = value.get('min', value.get('minimum', value.get('min_version', 0)))
        high = value.get('max', value.get('maximum', value.get('max_version')))
        return (0 if low is None else low, high)
    if isinstance(value, (list, tuple)):
        low = value[0] if value else 0
        high = value[1] if len(value) > 1 else None
        return (0 if low is None else low, high)
    if value is None:
        return (0, None)
    return (value, value)


def _dependency(item):
    if isinstance(item, str):
        return item, (0, None), None
    if isinstance(item, dict):
        name = item.get('name', item.get('package', item.get('pkg')))
        if name is None:
            if len(item) == 1:
                name, spec = next(iter(item.items()))
                return name, bounds(spec), None
            return None
        spec = item.get('range', item.get('versions', item.get('constraint')))
        if spec is None:
            if any(key in item for key in ('min', 'max', 'min_version', 'max_version')):
                spec = {
                    'min': item.get('min', item.get('min_version', 0)),
                    'max': item.get('max', item.get('max_version')),
                }
            elif 'version' in item:
                spec = item['version']
        return name, bounds(spec), item.get('feature')
    if isinstance(item, (list, tuple)) and item:
        name = item[0]
        if len(item) >= 3:
            spec = (item[1], item[2])
        elif len(item) == 2:
            spec = item[1]
        else:
            spec = None
        return name, bounds(spec), None
    return None


def dependencies(items, features=None):
    active_features = [] if features is None else features
    for item in items or []:
        parsed = _dependency(item)
        if parsed is None:
            continue
        name, dep_bounds, feature = parsed
        if feature is not None and feature != '' and feature not in active_features:
            continue
        yield name, dep_bounds
